struct Forma { std::string id, name, category = "Inne", kind = "launcher", script, args, stan, stan_key = "profil", stan_val, gpu_env, port_env, cmd, port = "8033", health = "/v1/models", ctx = "0", ram = "2", gpusel = "0", vram = "20000", extra, env, blad; bool edycja = false; json placements = json::array(); } F_;
std::string lacz(const json& a, const char* sep = " ") { std::string s; if (a.is_array()) for (auto& x : a) if (x.is_string()) { if (!s.empty()) s += sep; s += x.get<std::string>(); } return s; }
std::vector<std::string> dziel(const std::string& s, char sep = ' ') { std::vector<std::string> o; std::string c; for (char ch : s + std::string(1, sep)) { if (ch == sep) { if (!c.empty()) o.push_back(c); c.clear(); } else c += ch; } return o; }
void wczytajForme(const std::string& id) { F_ = Forma{}; Model* m = id.empty() ? nullptr : modelPoId(id); if (!m || m->surowy.empty()) return; auto j = json::parse(m->surowy, nullptr, false); if (j.is_discarded()) return; F_.edycja = true; auto S_ = [&](const char* k) { return j.contains(k) && j[k].is_string() ? j[k].get<std::string>() : std::string(); }; F_.id = S_("id"); F_.name = S_("name"); F_.category = S_("category"); F_.kind = S_("kind"); F_.script = S_("script"); F_.args = lacz(j.value("args", json::array())); F_.stan = S_("stan"); if (j.contains("stan_match") && j["stan_match"].is_object()) for (auto& [k, v] : j["stan_match"].items()) { F_.stan_key = k; if (v.is_string()) F_.stan_val = v; } F_.gpu_env = S_("gpu_env"); F_.port_env = S_("port_env"); F_.cmd = lacz(j.value("cmd", json::array())); F_.port = std::to_string(j.value("port", 0)); F_.health = S_("health"); F_.ctx = std::to_string(j.value("ctx", 0)); F_.ram = std::to_string(j.value("ram_gb", 0.)); F_.extra = lacz(j.value("extra_args", json::array())); F_.placements = j.value("placements", json::array()); if (!F_.placements.empty()) { std::string g; for (auto& x : F_.placements[0].value("gpus", json::array())) g += (g.empty() ? "" : ",") + std::to_string(x.get<int>()); F_.gpusel = g; auto v = F_.placements[0].value("vram", json::array()); if (!v.empty()) F_.vram = std::to_string(v[0].get<int>()); } if (j.contains("env") && j["env"].is_object()) for (auto& [k, v] : j["env"].items()) if (v.is_string()) F_.env += (F_.env.empty() ? "" : ",") + k + "=" + v.get<std::string>(); }
